import {
  AfterViewInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  HostBinding,
  inject,
  Input,
  numberAttribute,
  OnDestroy,
  Output,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { QDrawerContainerComponent } from './drawer-container/drawer-container.component';
import { QDrawerPosition } from './types/drawer-position.type';
import { QDrawerSnap } from './types/drawer-snap.interface';

interface HTMLElementWithPopover extends HTMLElement {
  showPopover: (options?: { source?: HTMLElement }) => void;
  hidePopover: () => void;
}

@Component({
  selector: 'dialog[q-drawer], dialog[qDrawer]',
  imports: [QDrawerContainerComponent],
  templateUrl: './drawer.component.html',
  styleUrl: './drawer.component.scss',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QDrawerComponent implements AfterViewInit, OnDestroy {
  @Output() readonly openStateChange = new EventEmitter<boolean>();

  @Input() title = '';
  @Input({ transform: booleanAttribute }) hasBorder = true;
  @Input({ transform: booleanAttribute }) showHeader = true;
  @Input({ transform: booleanAttribute }) hasBoxShadow = true;
  @Input({ transform: booleanAttribute }) showHeaderIcon = true;
  @Input({ transform: booleanAttribute }) titleCentered = false;
  @Input({ transform: booleanAttribute }) disableResize = false;
  @Input({ transform: booleanAttribute }) disableDefaultClose = false;
  @Input({ transform: booleanAttribute }) closeOnBackdropClick = true;
  @Input({ transform: booleanAttribute }) closeOnEsc = true;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-drawer';
  @Input() position: QDrawerPosition = 'bottom';
  @Input() snapList: QDrawerSnap[] = [
    { value: 0, type: '%' },
    { value: 50, type: '%' },
    { value: 100, type: '%' },
  ];

  @Input({ transform: booleanAttribute }) get hasBackdrop(): boolean {
    return this._hasBackdrop;
  }
  set hasBackdrop(value: boolean) {
    if (!value) {
      this._popoverAttr = 'manual';
    } else {
      this._popoverAttr = 'auto';
    }
    this._hasBackdrop = value;
  }

  @Input() get openState(): boolean {
    return this._openState;
  }
  set openState(value: boolean) {
    if (value === this._openState) return;
    this._openState = value;

    if (value) {
      this.open();
    } else {
      this.close();
    }
    this._cdr.markForCheck();
  }
  /**
   * @deprecated Use --awds-drawer-container-width token instead.
   * @breaking-change First major after 10 Mar 2026
   */
  @Input() width = '';
  /**
   *  @deprecated Use --awds-drawer-container-height token instead.
   *  @breaking-change First major after 10 Mar 2026
   */
  @Input() height = '146px';
  /**
   * @deprecated Use `--awds-drawer-offset-top` Component Level Tokens instead.
   * @breaking-change First major after 10 Mar 2026
   */
  @Input({ transform: numberAttribute }) offsetTop = 0;
  /**
   * @deprecated Use `--awds-drawer-offset-left` Component Level Tokens instead.
   * @breaking-change First major after 10 Mar 2026
   */
  @Input({ transform: numberAttribute }) offsetLeft = 0;
  /**
   * @deprecated Use `--awds-drawer-offset-right` Component Level Tokens instead.
   * @breaking-change First major after 10 Mar 2026
   */
  @Input({ transform: numberAttribute }) offsetRight = 0;
  /**
   * @deprecated Use `--awds-drawer-offset-bottom` Component Level Tokens instead.
   * @breaking-change First major after 10 Mar 2026
   */
  @Input({ transform: numberAttribute }) offsetBottom = 0;

  @HostBinding('class') get hostClasses(): string {
    return [
      'q-drawer',
      `q-drawer-${this.position}`,
      this.hasBorder && 'q-drawer-with-border',
      this.hasBoxShadow && 'q-drawer-with-box-shadow',
      this._rounded && 'q-drawer-rounded',
      this._fullscreen && 'q-drawer-fullscreen',
    ]
      .filter(Boolean)
      .join(' ');
  }

  @HostBinding('style')
  get _hostStyle(): string {
    return [
      `--drawer-offset-top: ${this.offsetTop}px`,
      `--drawer-offset-bottom: ${this.offsetBottom}px`,
      `--drawer-offset-left: ${this.offsetLeft}px`,
      `--drawer-offset-right: ${this.offsetRight}px`,
    ].join('; ');
  }

  @HostBinding('attr.popover') _popoverAttr: string | null = 'auto';

  @ViewChild('drawerContainer') _drawerContainer!: QDrawerContainerComponent;

  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _hostElement = inject<ElementRef<HTMLDialogElement>>(ElementRef).nativeElement;

  private _openState = false;
  private _fullscreen = false;
  private _hasBackdrop = true;
  private _focusOrigin: HTMLElement | null = null;

  ngAfterViewInit(): void {
    this._setupDialogEventListeners();
  }

  ngOnDestroy(): void {
    this.cleanUp();
  }

  open(focusOrigin?: HTMLElement): void {
    if (this.isOpened) return;
    this._drawerContainer._setInitialHeight();

    if (this.hasBackdrop) {
      this._hostElement.showModal();
    } else {
      this._focusOrigin = focusOrigin ?? (document.activeElement as HTMLElement);
      (this._hostElement as HTMLElementWithPopover).showPopover({ source: this._focusOrigin });
    }
    this._openState = true;
  }

  close(): void {
    this._hostElement.hidePopover();
    this._hostElement.close();
    this._focusOrigin?.focus();
    this._focusOrigin = null;
  }

  toggle(): void {
    if (this.isOpened) {
      this.close();
    } else {
      this.open();
    }
  }

  _onDrawerContainerClose(): void {
    if (!this.isOpened) return;
    this.close();
  }

  _onFullscreenChanged(isFullscreen: boolean): void {
    this._fullscreen = isFullscreen;
    this._cdr.markForCheck();
  }

  get isOpened(): boolean {
    return this._hostElement.open || this._hostElement.matches(':popover-open');
  }

  private _getCssTokensOffsetValue(name: string): number {
    const cssVarValue = getComputedStyle(this._hostElement).getPropertyValue(name).trim();
    const offsetValue = parseFloat(cssVarValue);
    return isNaN(offsetValue) ? 0 : offsetValue;
  }

  get _rounded(): boolean {
    const byInput = {
      top: this.offsetTop,
      bottom: this.offsetBottom,
      left: this.offsetLeft,
      right: this.offsetRight,
    }[this.position];
    if ((byInput ?? 0) > 0) return true;

    const byTokenName = {
      top: '--awds-drawer-offset-top',
      bottom: '--awds-drawer-offset-bottom',
      left: '--awds-drawer-offset-left',
      right: '--awds-drawer-offset-right',
    }[this.position];

    return this._getCssTokensOffsetValue(byTokenName) > 0;
  }

  private readonly _onDialogCancel = (event: Event): void => {
    if (this.disableDefaultClose || !this.closeOnEsc) {
      event.preventDefault();
    }
  };

  private readonly _onDialogMouseDown = (event: MouseEvent): void => {
    if (this.disableDefaultClose || !this.closeOnBackdropClick || !this.hasBackdrop) return;
    if (event.target === this._hostElement) {
      this.close();
    }
  };

  private readonly _onDialogKeyDown = (event: KeyboardEvent): void => {
    if (event.key !== 'Escape') return;
    if (this.hasBackdrop) {
      if (this.disableDefaultClose || !this.closeOnEsc) {
        event.preventDefault();
        event.stopPropagation();
      }
      return;
    }

    if (this.disableDefaultClose || !this.closeOnEsc) {
      event.preventDefault();
      return;
    }
    this.close();
  };

  private _handleBeforeToggle = (event: Event): void => {
    const toggleEvent = event as ToggleEvent;

    if (toggleEvent.newState === 'open') {
      requestAnimationFrame(() => {
        this._openState = true;
        this.openStateChange.emit(true);
      });
    } else if (toggleEvent.newState === 'closed') {
      requestAnimationFrame(() => {
        this._openState = false;
        this.openStateChange.emit(false);
      });
    }
  };

  private _setupDialogEventListeners(): void {
    this._hostElement.addEventListener('cancel', this._onDialogCancel);
    this._hostElement.addEventListener('mousedown', this._onDialogMouseDown);
    this._hostElement.addEventListener('keydown', this._onDialogKeyDown);
    this._hostElement.addEventListener('beforetoggle', this._handleBeforeToggle);
  }

  private cleanUp(): void {
    this._hostElement.removeEventListener('cancel', this._onDialogCancel);
    this._hostElement.removeEventListener('mousedown', this._onDialogMouseDown);
    this._hostElement.removeEventListener('keydown', this._onDialogKeyDown);
    this._hostElement.removeEventListener('beforetoggle', this._handleBeforeToggle);
  }
}
