import { A11yModule } from '@angular/cdk/a11y';
import { BreakpointObserver, BreakpointState } from '@angular/cdk/layout';
import { NgTemplateOutlet } from '@angular/common';
import {
  AfterViewInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  DOCUMENT,
  ElementRef,
  EventEmitter,
  HostBinding,
  inject,
  Input,
  OnChanges,
  OnInit,
  Output,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { QInteractiveIconComponent } from '@questrade/allspark-angular-components/interactive-icon';
import { clear } from '@questrade/allspark-icons/icons';
import { fromEvent, takeUntil, takeWhile } from 'rxjs';
import { QDrawerPosition } from '../types/drawer-position.type';
import { QDrawerSnap } from '../types/drawer-snap.interface';

const MIN_HEIGHT = 146;
const CLICK_DRAG_THRESHOLD_PX = 5;

@Component({
  selector: 'q-drawer-container',
  imports: [QInteractiveIconComponent, NgTemplateOutlet, A11yModule],
  providers: [QDestroyService],
  templateUrl: './drawer-container.component.html',
  styleUrl: './drawer-container.component.scss',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QDrawerContainerComponent implements OnInit, AfterViewInit, OnChanges {
  @Output() readonly closeRequested = new EventEmitter<void>();
  @Output() readonly closeIconClicked = new EventEmitter<void>();
  @Output() readonly fullscreenChange = new EventEmitter<boolean>();

  @Input() title = '';
  @Input() position: QDrawerPosition = 'bottom';
  @Input({ transform: booleanAttribute }) showHeader = true;
  @Input({ transform: booleanAttribute }) showHeaderIcon = true;
  @Input({ transform: booleanAttribute }) disableDefaultClose = false;
  @Input({ transform: booleanAttribute }) disableResize = false;
  @Input() snapList: QDrawerSnap[] = [
    { value: 0, type: '%' },
    { value: 50, type: '%' },
    { value: 100, type: '%' },
  ];
  // TODO: Remove this width input when the deprecation from Drawer component is removed
  @Input() width = '';
  // TODO: Remove this height input when the deprecation from Drawer component is removed
  @Input() height = '146px';
  // TODO: Remove this titleCentered input when the deprecation from Drawer component is removed
  @Input({ transform: booleanAttribute }) titleCentered = false;

  @ViewChild('header') _header!: ElementRef<HTMLElement>;
  @ViewChild('content') _content!: ElementRef<HTMLElement>;
  @ViewChild('closeIcon', { read: ElementRef }) _closeIcon: ElementRef<HTMLElement> | null = null;

  @HostBinding('attr.data-qt') _dataQt = 'q-drawer-container';
  @HostBinding('style.min-height') get _minHeight(): string {
    return !this._isMobile && this._topOrBottom
      ? `var(--awds-drawer-container-min-height, ${MIN_HEIGHT}px)`
      : '';
  }

  @HostBinding('style.width') get _width(): string {
    if (this._isMobile && this._topOrBottom) return '100vw';
    const fallbackWidth = this.width || '100%';
    return `var(--awds-drawer-container-width, ${fallbackWidth})`;
  }

  @HostBinding('style.margin-left') get _marginLeft(): string {
    return this._topOrBottom && !!this.width ? 'auto' : '';
  }

  @HostBinding('style.margin-right') get _marginRight(): string {
    return this._topOrBottom && !!this.width ? 'auto' : '';
  }

  @HostBinding('class') get _hostClasses(): string {
    return [
      'q-drawer-container',
      `q-drawer-container-${this.position}`,
      this._resizing && 'q-drawer-container-resizing',
    ]
      .filter(Boolean)
      .join(' ');
  }

  _isMobile = false;

  private _resizing = false;
  private _fullscreen = false;
  private _snapEnabled = true;
  private _dragStartYValue = 0;
  private _dragStartDrawerHeight = 0;

  private readonly _document = inject(DOCUMENT);
  private readonly _elementRef = inject(ElementRef);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _breakpointObserver = inject(BreakpointObserver);

  ngOnInit(): void {
    this._iconRegistry.registerIcons([clear]);

    this._breakpointObserver
      .observe(['(max-width: 599px)'])
      .pipe(takeUntil(this._destroy$))
      .subscribe((result: BreakpointState) => {
        this._isMobile = result.matches;
        this._cdr.markForCheck();
      });
  }

  ngOnChanges(changes: SimpleChanges): void {
    const { height, position, snapList } = changes;

    if (height || position || snapList) {
      this._setInitialHeight();
      this._cdr.markForCheck();
    }
  }

  ngAfterViewInit(): void {
    this._subscribeToDocumentMouseEvents();

    if (this.position === 'bottom' && this._header) {
      this._subscribeToHeaderTouchEvents();
    }
  }

  _onTouchStart(event: TouchEvent): void {
    if (!this._targetIsCloseIcon(event.target) && event.cancelable) {
      event.preventDefault();
    }
    if (event.touches[0]) {
      this._prepareToResize(event.touches[0].clientY);
    }
  }

  _onTouchCancel(event: TouchEvent): void {
    if (!this._targetIsCloseIcon(event.target)) {
      event.preventDefault();
    }
    if (event.touches[0]) {
      this._stopResize(event.touches[0].clientY);
    }
  }

  _onTouchMove(event: TouchEvent): void {
    if (!this._targetIsCloseIcon(event.target) && event.cancelable) {
      event.preventDefault();
    }
    if (event.touches[0]) {
      this._resize(event.touches[0].clientY);
    }
  }

  _onTouchEnd(event: TouchEvent): void {
    if (!this._targetIsCloseIcon(event.target)) {
      event.preventDefault();
    }
    if (event.changedTouches[0]) {
      this._stopResize(event.changedTouches[0].clientY);
    }
  }

  _onHandleMouseDown(event: MouseEvent): void {
    this._prepareToResize(event.clientY);
  }

  _onCloseIconClick(event: Event): void {
    event.preventDefault();
    event.stopPropagation();

    if (this.disableDefaultClose) return;

    this.closeIconClicked.emit();
  }

  _setInitialHeight(): void {
    if (this.position === 'left' || this.position === 'right') {
      this._el.style.height = '100%';
    } else {
      let usePercentageValue = false;
      let percentageValue = 0;

      if (this.height.endsWith('%')) {
        const strValue = this.height.slice(0, -1);
        const isValidPercentageValue = !isNaN(+strValue);

        if (isValidPercentageValue) {
          usePercentageValue = true;
          percentageValue = +strValue;
        }
      }

      const heightValueToUse = this.height || MIN_HEIGHT + 'px';

      const defaultHeight = usePercentageValue
        ? `calc(100vh * ${percentageValue / 100})`
        : heightValueToUse;

      const finalHeight = `var(--awds-drawer-container-height, ${defaultHeight})`;

      const filteredSnapValues = this._sortedSnapValues.filter((i) => i !== 0);

      const getMobileHeight = (): string =>
        filteredSnapValues.length ? `${filteredSnapValues[0]}px` : finalHeight;

      this._el.style.height = this._isMobile ? getMobileHeight() : finalHeight;
    }
  }

  private _prepareToResize(dragStartYValue: number): void {
    if (!this._isMobile || this.disableResize) return;

    this._dragStartDrawerHeight = this._el.getBoundingClientRect().height;
    this._dragStartYValue = dragStartYValue;
    this._resizing = true;
    this._fullscreen = false;
    this.fullscreenChange.emit(this._fullscreen);
    this._cdr.markForCheck();
  }

  private _stopResize(releasedAtY: number): void {
    if (!this._isMobile || this.disableResize) return;

    const movedDistance = Math.abs(this._dragStartYValue - releasedAtY);
    this._dragStartDrawerHeight = 0;
    this._resizing = false;
    this._cdr.markForCheck();

    if (movedDistance < CLICK_DRAG_THRESHOLD_PX) {
      return;
    }

    if (this._snapEnabled) {
      this._snap(releasedAtY);
    }
  }

  private _resize(clientY: number): void {
    if (!this._resizing || !this._dragStartDrawerHeight) return;

    const hightDelta = this._dragStartYValue - clientY;
    this._el.style.height =
      this.position === 'bottom'
        ? this._dragStartDrawerHeight + hightDelta + 'px'
        : this._dragStartDrawerHeight - hightDelta + 'px';
  }

  private _subscribeToHeaderTouchEvents(): void {
    fromEvent<TouchEvent>(this._header.nativeElement, 'touchstart')
      .pipe(
        takeWhile(() => this.position === 'bottom'),
        takeUntil(this._destroy$),
      )
      .subscribe((event: TouchEvent) => {
        this._onTouchStart(event);
      });

    fromEvent<TouchEvent>(this._header.nativeElement, 'touchend')
      .pipe(
        takeWhile(() => this.position === 'bottom'),
        takeUntil(this._destroy$),
      )
      .subscribe((event: TouchEvent) => {
        this._onTouchEnd(event);
      });

    fromEvent<TouchEvent>(this._header.nativeElement, 'touchcancel')
      .pipe(
        takeWhile(() => this.position === 'bottom'),
        takeUntil(this._destroy$),
      )
      .subscribe((event: TouchEvent) => {
        this._onTouchCancel(event);
      });

    fromEvent<TouchEvent>(this._header.nativeElement, 'touchmove')
      .pipe(
        takeWhile(() => this.position === 'bottom'),
        takeUntil(this._destroy$),
      )
      .subscribe((event: TouchEvent) => {
        this._onTouchMove(event);
      });

    fromEvent<MouseEvent>(this._header.nativeElement, 'mousedown')
      .pipe(
        takeWhile(() => this.position === 'bottom'),
        takeUntil(this._destroy$),
      )
      .subscribe((event: MouseEvent) => {
        this._onHandleMouseDown(event);
      });
  }

  private _subscribeToDocumentMouseEvents(): void {
    fromEvent<MouseEvent>(document, 'mousemove')
      .pipe(takeUntil(this._destroy$))
      .subscribe((event: MouseEvent) => {
        this._onDocumentMouseMove(event);
      });

    fromEvent<MouseEvent>(document, 'mouseup')
      .pipe(takeUntil(this._destroy$))
      .subscribe((event: MouseEvent) => {
        this._onDocumentMouseUp(event);
      });
  }

  private _onDocumentMouseMove(event: MouseEvent): void {
    if (!this._resizing) return;
    this._resize(event.clientY);
  }

  private _onDocumentMouseUp(event: MouseEvent): void {
    if (!this._resizing) return;
    this._stopResize(event.clientY);
  }

  private _snap(releasedAtY: number): void {
    if (!this._snapEnabled) return;

    const releasedAt = this.position === 'bottom' ? this._totalHeight - releasedAtY : releasedAtY;
    const closestSnapValue = this._getClosestSnapValue(releasedAt);

    if (closestSnapValue === 0) {
      this.closeRequested.emit();
    } else {
      // wait for css changes that enable animation
      setTimeout(() => {
        this._el.style.height = closestSnapValue + 'px';
        this._fullscreen = closestSnapValue === this._totalHeight;
        this.fullscreenChange.emit(this._fullscreen);
        this._cdr.markForCheck();
      }, 0);
    }
  }

  private _percentToPx = (percent: number): number => {
    return (this._totalHeight * percent) / 100;
  };

  private _getClosestSnapValue(releasedAt: number): number {
    return this._sortedSnapValues.reduce((prev, curr) =>
      Math.abs(curr - releasedAt) < Math.abs(prev - releasedAt) ? curr : prev,
    );
  }

  private get _el(): HTMLElement {
    return this._elementRef.nativeElement;
  }

  private get _totalHeight(): number {
    return this._document.documentElement.clientHeight;
  }

  private get _sortedSnapValues(): number[] {
    const sortedSnapValues = this.snapList
      .map((item) => (item.type === 'px' ? item.value : this._percentToPx(item.value)))
      .sort((a, b) => a - b);

    return this.disableDefaultClose ? sortedSnapValues.filter((i) => i !== 0) : sortedSnapValues;
  }

  private get _topOrBottom(): boolean {
    return this.position === 'top' || this.position === 'bottom';
  }

  private _targetIsCloseIcon(target: EventTarget | null): boolean {
    if (!target) return false;

    return this._closeIcon?.nativeElement.contains(target as HTMLElement) ?? false;
  }
}
